import{_ as a,o as r,c as o,a0 as e}from"./chunks/framework.D7EjqxMK.js";const u=JSON.parse('{"title":"模块三：高级话题（ROS 2 底层实现）","description":"","frontmatter":{},"headers":[],"relativePath":"08-ros/03_高级话题/README.md","filePath":"08-ros/03_高级话题/README.md"}'),d={name:"08-ros/03_高级话题/README.md"};function l(s,t,n,i,h,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="模块三-高级话题-ros-2-底层实现" tabindex="-1">模块三：高级话题（ROS 2 底层实现） <a class="header-anchor" href="#模块三-高级话题-ros-2-底层实现" aria-label="Permalink to &quot;模块三：高级话题（ROS 2 底层实现）&quot;">​</a></h1><blockquote><p><strong>位置</strong>：<code>08-ros / 03_高级话题</code><strong>难度</strong>：全 ⭐（入门门槛高 —— 面向已具备 ROS 2 使用经验的进阶读者，需 C++/Linux 功底） <strong>前置模块</strong>：<a href="./../01_基础概念/README.html">模块一 · 基础概念</a>、<a href="./../02_核心模块/README.html">模块二 · 核心模块</a></p></blockquote><hr><h2 id="导读" tabindex="-1">导读 <a class="header-anchor" href="#导读" aria-label="Permalink to &quot;导读&quot;">​</a></h2><p>本模块是 ROS 2 知识库里<strong>最偏底层</strong>的一部分，目标是让你从&quot;会用话题/服务/参数&quot;上升到&quot;能解释并调优 ROS 2 的运行时行为&quot;。六篇文章从架构分层出发，逐层深入线程模型、实时性、进程内通信、安全与中间件选型——这些都是<strong>高级岗/系统岗面试与真实项目调优的高频战场</strong>。</p><h2 id="主题清单" tabindex="-1">主题清单 <a class="header-anchor" href="#主题清单" aria-label="Permalink to &quot;主题清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>文档</th><th>主题</th><th>难度</th></tr></thead><tbody><tr><td>01</td><td><a href="./01_ROS2架构分层详解.html">ROS 2 架构分层详解</a></td><td>rcl / rmw / DDS 分层、Context、waitset、guard condition</td><td>⭐</td></tr><tr><td>02</td><td><a href="./02_线程模型与Executor深度解析.html">线程模型与 Executor 深度解析</a></td><td>Callback Group、单/多线程执行器、死锁、GIL</td><td>⭐</td></tr><tr><td>03</td><td><a href="./03_实时性与任务调度.html">实时性与任务调度</a></td><td>PREEMPT_RT、SCHED_FIFO、RT 纪律、cyclictest</td><td>⭐</td></tr><tr><td>04</td><td><a href="./04_组件化与进程内通信.html">组件化与进程内通信</a></td><td>Composable Node、intra-process、SHM、零拷贝</td><td>⭐</td></tr><tr><td>05</td><td><a href="./05_ROS2安全架构(SROS2).html">ROS 2 安全架构（SROS2）</a></td><td>DDS-Security、认证/加密/访问控制、信任域</td><td>⭐</td></tr><tr><td>06</td><td><a href="./06_RMW实现对比(FastDDS_vs_CycloneDDS).html">RMW 实现对比（Fast DDS vs Cyclone DDS）</a></td><td>rmw 抽象、切换、TSC 报告、选型</td><td>⭐</td></tr></tbody></table><h2 id="建议学习顺序" tabindex="-1">建议学习顺序 <a class="header-anchor" href="#建议学习顺序" aria-label="Permalink to &quot;建议学习顺序&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 架构分层 → 02 线程模型/Executor → 03 实时性 → 04 组件化/进程内通信 → 06 RMW 对比 → 05 安全(SROS2)</span></span></code></pre></div><ul><li><strong>01</strong> 是全模块的地基：先建立 <code>rcl → rmw → DDS</code> 的调用链心智模型。</li><li><strong>02/03</strong> 紧贴 01 的 waitset 机制，讲调度与实时，是性能调优的主线。</li><li><strong>04</strong> 是 01 的&quot;优化路径&quot;：跳过 DDS 的 intra-process 与组件化。</li><li><strong>06</strong> 回到 rmw 层做选型；<strong>05</strong> 放到最后，因为安全叠加在 DDS-Security 之上，理解前几篇的握手/发现后更容易吃透。</li></ul><h2 id="贯穿全模块的三条红线-自查" tabindex="-1">贯穿全模块的三条红线（自查） <a class="header-anchor" href="#贯穿全模块的三条红线-自查" aria-label="Permalink to &quot;贯穿全模块的三条红线（自查）&quot;">​</a></h2><ol><li><strong>底层优先</strong>：每篇第 3 节必须落到类名/函数名/头文件（如 <code>rcl_wait</code>、<code>rmw_publish</code>、<code>rclcpp::CallbackGroup::can_be_taken_from_</code>、<code>rmw_qos_profile_t</code>）。</li><li><strong>数字必溯源</strong>：所有性能/延迟/吞吐数字要么给来源，要么标注&quot;待验证&quot;，<strong>绝不编造基准数据</strong>。</li><li><strong>交叉引用</strong>：与前/后模块及本模块其余文章用相对链接互链，形成知识网络。</li></ol><h2 id="前置模块链接" tabindex="-1">前置模块链接 <a class="header-anchor" href="#前置模块链接" aria-label="Permalink to &quot;前置模块链接&quot;">​</a></h2><ul><li><a href="./../01_基础概念/README.html">模块一 · 基础概念</a> —— 话题/服务/参数、QoS 基础</li><li><a href="./../02_核心模块/README.html">模块二 · 核心模块</a> —— 节点、launch、tf、生命周期等</li><li>后续：<a href="./../04_工程实践/README.html">模块四 · 工程实践</a> —— 部署、测试、CI、容器化</li></ul>',14)])])}const p=a(d,[["render",l]]);export{u as __pageData,p as default};
